def _init():
    return {'recipe':jnp.int32(-1), 'items':jnp.zeros((81,5),jnp.int32), 'time':jnp.int32(0), 'was_dish':jnp.bool_(False), 'verified':jnp.zeros((2,),jnp.bool_), 'bad_signal':jnp.bool_(False), 'authoritative':jnp.bool_(False), 'cycle_age':jnp.int32(0), 'inferred_cycles':jnp.int32(0), 'last_recipe':jnp.int32(0), 'cue_verified':jnp.zeros((81,2),jnp.bool_), 'partner_cell':jnp.int32(-1), 'partner_signal':jnp.int32(-1), 'partner_streak':jnp.int32(0), 'outer_stall':jnp.int32(0), 'rescue_active':jnp.bool_(False), 'rescue_credit':jnp.bool_(True), 'rescue_button':jnp.int32(22), 'verification_count':jnp.zeros((2,),jnp.int32), 'cycle_calibrated':jnp.bool_(False)}

def init_agent_0(): return _init()
def init_agent_1(): return _init()


def _decode(obs,memory,reset):
    memory=jax.tree.map(lambda x,y:jnp.where(reset,x,y),_init(),memory)
    error=jnp.sum(jnp.abs(jnp.asarray(_CROPS)-obs[None,:,:,20:29]),axis=(1,2,3))
    pos=jnp.asarray(_POSITIONS)[jnp.argmin(error)]
    direction=jnp.argmax(obs[2,2,1:5])
    state=(pos[0]*9+pos[1])*4+direction
    inv=obs[2,2,5:10]
    # Gather the current local crop onto the known global board.
    rr=jnp.arange(9)[:,None]-pos[0]+2
    cc=jnp.arange(9)[None,:]-pos[1]+2
    seen=(rr>=0)&(rr<5)&(cc>=0)&(cc<5)
    local=obs[jnp.clip(rr,0,4),jnp.clip(cc,0,4),29:34].reshape(81,5)
    items=jnp.where(seen.reshape(81,1),local,memory['items'])
    displayed=jnp.sum(obs[:,:,36:39],axis=(0,1))
    recipe=jnp.where(jnp.sum(displayed)>0,jnp.argmax(displayed),memory['recipe'])
    return memory,pos,state,inv,items,recipe


def _go(state,target):
    costs=jnp.asarray(_DIST)[target,jnp.asarray(_NEXT)[state]]
    return jnp.where(jnp.asarray(_DIST)[target,state]==0,5,jnp.argmin(costs)).astype(jnp.int32)


def _nearest(state,mask):
    return jnp.argmin(jnp.where(mask,jnp.asarray(_DIST)[:,state],9999))


def agent_0_act(obs,reset,memory,rng):
    memory,pos,state,inv,items,recipe=_decode(obs,memory,reset)
    raw=jnp.argmax(inv[2:])
    empty=jnp.sum(inv)==0
    target_supply=jnp.where(recipe==1,5*9+2,3*9+2)
    # Maintain a visible, semantically meaningful ingredient at its supply.
    drop=_nearest(state,jnp.asarray(_WALLS)&(jnp.sum(items,axis=1)==0))
    # Reuse ingredients left on counters after earlier recipe changes.
    pickup=_nearest(state,jnp.asarray(_WALLS)&(items[:,2+jnp.maximum(recipe,0)]==1)&(items[:,0]==0))
    pickup=jnp.where(jnp.asarray(_DIST)[pickup,state]<jnp.asarray(_DIST)[target_supply,state],pickup,target_supply)
    target=jnp.where(empty,pickup,jnp.where(raw==recipe,target_supply,drop))
    action=_go(state,target)
    action=jnp.where((~empty)&(raw==recipe)&(jnp.asarray(_DIST)[target_supply,state]==0),4,action)
    # When no free indicator is in view, move toward one on the outer ring.
    indicator=_nearest(state,jnp.asarray(_INDICATORS))
    action=jnp.where(recipe<0,_go(state,indicator),action)
    partner_local=jnp.array(jnp.unravel_index(jnp.argmax(obs[:,:,10]),(5,5)))
    partner_visible=jnp.sum(obs[:,:,10])>0
    partner_pos=pos+partner_local-2
    partner_cell=partner_pos[0]*9+partner_pos[1]
    partner_inventory=obs[partner_local[0],partner_local[1],15:20]
    partner_empty=jnp.sum(partner_inventory)==0
    stalled=partner_visible&partner_empty&(partner_cell==memory['partner_cell'])
    stall=jnp.where(stalled,memory['outer_stall']+1,0)
    progress=partner_visible&(~partner_empty)
    credit=memory['rescue_credit']|progress
    trigger=(stall>=24)&credit&(memory['time']<335)
    active=memory['rescue_active']|trigger
    button=jnp.where(trigger,jnp.where(partner_pos[0]<=4,22,58),memory['rescue_button'])
    rescue_target=jnp.where(empty,button,drop)
    action=jnp.where(active,_go(state,rescue_target),action)
    activated=active&empty&(jnp.asarray(_DIST)[button,state]==0)
    active=active&(~activated)
    credit=credit&(~activated)
    nxt={**memory,'recipe':recipe,'items':items,'time':memory['time']+1,'was_dish':inv[1]>0,
         'partner_cell':jnp.where(partner_visible,partner_cell,-1),'outer_stall':stall,
         'rescue_active':active,'rescue_credit':credit,'rescue_button':button}
    return action.astype(jnp.int32),nxt,{'pos':pos,'recipe':recipe,'inventory':inv,'target':jnp.where(active,rescue_target,target),'rescue':activated,'stall':stall}



def agent_1_act(obs,reset,memory,rng):
    memory,pos,state,inv,items,recipe=_decode(obs,memory,reset)
    delivered=memory['was_dish']&(inv[1]==0)
    fresh_display=jnp.sum(obs[:,:,36:39])>0
    recipe=jnp.where(delivered&(~fresh_display),-1,recipe)
    age=jnp.where(delivered,0,memory['cycle_age']+1)
    displayed=jnp.sum(obs[:,:,36:39],axis=(0,1))
    authority=jnp.where(delivered,False,memory['authoritative']) | (jnp.sum(displayed)>0)
    partner_local=jnp.array(jnp.unravel_index(jnp.argmax(obs[:,:,10]),(5,5)))
    partner_pos=pos+partner_local-2
    partner=obs[partner_local[0],partner_local[1],15:20]
    partner_visible=jnp.sum(obs[:,:,10])>0
    raw_signal=jnp.argmax(partner[2:])
    raw=(partner[0]==0)&(jnp.sum(partner[2:])==1)&(raw_signal<2)
    at_supply=(partner_pos[1]==1)&((partner_pos[0]==3)|(partner_pos[0]==5))
    position_signal=jnp.where(partner_pos[0]==5,1,0)
    signal=jnp.where(raw,raw_signal,position_signal)
    cue_present=partner_visible&(raw|((jnp.sum(partner)==0)&at_supply))
    cell=jnp.clip(partner_pos[0]*9+partner_pos[1],0,80)
    same_cue=(cell==memory['partner_cell'])&(signal==memory['partner_signal'])
    streak=jnp.where(cue_present,jnp.where(same_cue,memory['partner_streak']+1,1),0)
    grounded=cue_present&(streak>=2)
    verified=memory['verified']
    confirm=grounded&authority&(recipe==signal)&(age>=6)
    verified=verified.at[jnp.minimum(signal,1)].set(verified[jnp.minimum(signal,1)]|confirm)
    cycle_calibrated=memory['cycle_calibrated']&(~delivered)
    new_confirmation=confirm&(~cycle_calibrated)
    verification_count=memory['verification_count'].at[jnp.minimum(signal,1)].add(new_confirmation.astype(jnp.int32))
    cycle_calibrated=cycle_calibrated|confirm
    cue_verified=memory['cue_verified'].at[cell,jnp.minimum(signal,1)].set(memory['cue_verified'][cell,jnp.minimum(signal,1)]|confirm)
    bad=memory['bad_signal']|(grounded&authority&(recipe!=signal)&(age>=10))
    calibrated=jnp.all(verified)&(~bad)
    inferred_cycles=jnp.where(authority,0,memory['inferred_cycles'])
    audit_limit=jnp.where(jnp.all(verification_count>=2),3,2)
    inference_allowed=calibrated&(inferred_cycles<audit_limit)
    infer=(recipe<0)&inference_allowed&grounded&cue_verified[cell,jnp.minimum(signal,1)]&(age>=3)
    recipe=jnp.where(infer,signal,recipe)
    inferred_cycles=inferred_cycles+infer.astype(jnp.int32)
    last_recipe=jnp.where(recipe>=0,recipe,memory['last_recipe'])
    pot=items[4*9+4]
    count=jnp.sum(pot[2:])
    has_raw=(jnp.sum(inv[2:])>0)&(inv[0]==0)
    empty=jnp.sum(inv)==0
    button=jnp.where(jnp.asarray(_DIST)[2*9+4,state]<=jnp.asarray(_DIST)[6*9+4,state],2*9+4,6*9+4)
    supply=jnp.where(recipe==1,5*9+2,3*9+2)
    plate=jnp.where(jnp.asarray(_DIST)[3*9+6,state]<=jnp.asarray(_DIST)[5*9+6,state],3*9+6,5*9+6)
    goal=jnp.where(jnp.asarray(_DIST)[4*9+2,state]<=jnp.asarray(_DIST)[4*9+6,state],4*9+2,4*9+6)
    target=jnp.where(recipe<0,button,supply)
    inspect=(recipe<0)&inference_allowed&(age<9)
    viewpoint=jnp.where(last_recipe==1,5*9+2,3*9+2)
    target=jnp.where(inspect,viewpoint,target)
    target=jnp.where((count>=3)&empty,plate,target)
    target=jnp.where(has_raw|(inv[0]>0),4*9+4,target)
    at_left=(pos[0]==4)&(pos[1]==3)
    target=jnp.where((inv[0]>0)&(inv[1]==0)&(~at_left),4*9+2,target)
    target=jnp.where(inv[1]>0,4*9+2,target)
    action=_go(state,target)
    action=jnp.where(inspect&(jnp.asarray(_DIST)[viewpoint,state]==0),4,action)
    action=jnp.where((inv[0]>0)&(inv[1]==0)&at_left&(jnp.asarray(_DIST)[4*9+4,state]==0)&(pot[1]==0),4,action)
    action=jnp.where((recipe<0)&(memory['time']>360),4,action)
    nxt={**memory,'recipe':recipe,'items':items,'time':memory['time']+1,'was_dish':inv[1]>0,
         'verified':verified,'bad_signal':bad,'authoritative':authority,'cycle_age':age,
         'inferred_cycles':inferred_cycles,'last_recipe':last_recipe,'cue_verified':cue_verified,
         'partner_cell':jnp.where(cue_present,cell,-1),'partner_signal':jnp.where(cue_present,signal,-1),'partner_streak':streak,
         'verification_count':verification_count,'cycle_calibrated':cycle_calibrated}
    timer=jnp.sum(obs[:,:,39])
    return action.astype(jnp.int32),nxt,{'pos':pos,'recipe':recipe,'inventory':inv,'target':target,'pot':pot,'timer':timer,'delivered':delivered,'verified':verified,'bad':bad,'infer':infer,'age':age,'signal':jnp.where(grounded,signal,-1),'authority':authority,'verification_count':verification_count}
